import{_ as i}from"./chunks/smart-groups-new.hrKzalJR.js";import{_ as a,c as r,o as t,ae as s}from"./chunks/framework.DMK_uHmU.js";const o="/help-center/assets/smart-groups-builder.CJIdHCCV.png",l="/help-center/assets/smart-groups-users.B4BBIqwQ.png",n="/help-center/assets/smart-groups-kbs.CL6EzoGu.png",y=JSON.parse('{"title":"Smart Group Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Groups/smart-group.md","filePath":"Administration/Manage/Groups/smart-group.md"}'),u={name:"Administration/Manage/Groups/smart-group.md"};function p(g,e,d,m,c,h){return t(),r("div",null,e[0]||(e[0]=[s('<h1 id="smart-group-configuration-guide" tabindex="-1">Smart Group Configuration Guide <a class="header-anchor" href="#smart-group-configuration-guide" aria-label="Permalink to &quot;Smart Group Configuration Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Smart Group Configuration system provides powerful tools for creating and managing dynamic user groups that automatically update based on defined criteria. This guide covers the three main components of the system: GroupDialog, GroupMembers, and GroupAssignedKbs.</p><h2 id="smart-group-dialog" tabindex="-1">Smart Group Dialog <a class="header-anchor" href="#smart-group-dialog" aria-label="Permalink to &quot;Smart Group Dialog&quot;">​</a></h2><p>The Smart Group Dialog is the primary interface for creating, configuring, and managing smart groups. It provides a comprehensive set of tools for setting group properties, defining membership criteria, and reviewing group composition.</p><h3 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h3><p>The top section of the dialog contains fields for essential group information:</p><p><img src="'+i+'" alt="homepage"></p><ol><li><p><strong>Group Name</strong> (Required): The primary identifier for the group</p><ul><li>Must be unique within the system</li><li>Used for display and reference throughout the application</li></ul></li><li><p><strong>Group Description</strong>: Additional context about the group&#39;s purpose</p><ul><li>Should clearly explain the group&#39;s function and membership criteria</li><li>Helps administrators understand the group&#39;s purpose at a glance</li></ul></li><li><p><strong>Initials</strong> (Required): Two-character identifier used for the group avatar</p><ul><li>Automatically generated from the first two letters of the group name</li><li>Can be manually overridden if needed</li><li>Used in visual representations of the group throughout the system</li></ul></li><li><p><strong>Hidden Fields</strong>: System information including:</p><ul><li>Group ID: Auto-generated unique identifier</li><li>Group Type: Security classification (default)</li><li>Group Rule: Query definition that determines membership</li></ul></li></ol><h3 id="smart-group-builder-interface" tabindex="-1">Smart Group Builder Interface <a class="header-anchor" href="#smart-group-builder-interface" aria-label="Permalink to &quot;Smart Group Builder Interface&quot;">​</a></h3><p>The Smart Group Builder tab provides a powerful query interface for defining membership criteria:</p><p><img src="'+o+'" alt="homepage"></p><ol><li><p><strong>Query Builder</strong>: Allows you to create complex conditions that determine group membership</p><ul><li><strong>Fields</strong>: Select from user properties like name, department, title, etc.</li><li><strong>Operators</strong>: Choose logical operators (contains, equals, starts with, etc.)</li><li><strong>Values</strong>: Enter the specific values to match</li></ul></li><li><p><strong>Query Logic</strong>:</p><ul><li><strong>AND</strong>: All conditions must be true for a user to be included</li><li><strong>OR</strong>: Any matching condition will include a user</li><li><strong>Nested Conditions</strong>: Create complex logic by combining AND/OR groups</li></ul></li><li><p><strong>Help Panel</strong>: Toggle-able information explaining how to use the query builder</p><ul><li>Explains the function of AND/OR logic</li><li>Describes how to add, remove, and clone conditions</li><li>Provides guidance on effective query construction</li></ul></li></ol><h3 id="managing-group-membership" tabindex="-1">Managing Group Membership <a class="header-anchor" href="#managing-group-membership" aria-label="Permalink to &quot;Managing Group Membership&quot;">​</a></h3><p>The Users in Group tab shows all users who match the defined criteria:</p><p><img src="'+l+'" alt="homepage"></p><ol><li><p><strong>Member List</strong>: Displays all users who currently match the group&#39;s query criteria</p><ul><li>Shows user details including name, username, and access level</li><li>Updates automatically when the query is modified</li></ul></li><li><p><strong>Membership Count</strong>: Badge showing the total number of users in the group</p><ul><li>Updates in real-time as group criteria changes</li><li>Provides quick visibility into group size</li></ul></li></ol><h3 id="knowledge-base-assignments" tabindex="-1">Knowledge Base Assignments <a class="header-anchor" href="#knowledge-base-assignments" aria-label="Permalink to &quot;Knowledge Base Assignments&quot;">​</a></h3><p>The Assigned KBs tab shows knowledge bases that are associated with this group:</p><p><img src="'+n+'" alt="homepage"></p><ol><li><strong>Knowledge Base List</strong>: Shows all knowledge bases assigned to this group <ul><li>Displays KB name, initials, and description</li><li>Links to the Knowledge Base Manager for making assignments</li></ul></li></ol><h3 id="membership-changes-tracking" tabindex="-1">Membership Changes Tracking <a class="header-anchor" href="#membership-changes-tracking" aria-label="Permalink to &quot;Membership Changes Tracking&quot;">​</a></h3><p>The system tracks and displays changes to group membership when updating an existing group:</p><ol><li><p><strong>Users Added</strong>: Shows users newly added to the group after a rule change</p><ul><li>Appears as a tab when users are added</li><li>Displays a count badge with the number of additions</li></ul></li><li><p><strong>Users Removed</strong>: Shows users removed from the group after a rule change</p><ul><li>Appears as a tab when users are removed</li><li>Displays a count badge with the number of removals</li></ul></li><li><p><strong>Success Message</strong>: After saving, displays a summary of membership changes</p><ul><li>Total users in the group</li><li>Number of users added</li><li>Number of users removed</li></ul></li></ol><h2 id="group-members-component" tabindex="-1">Group Members Component <a class="header-anchor" href="#group-members-component" aria-label="Permalink to &quot;Group Members Component&quot;">​</a></h2><p>The Group Members component displays and manages user membership within a group.</p><h3 id="members-list-interface" tabindex="-1">Members List Interface <a class="header-anchor" href="#members-list-interface" aria-label="Permalink to &quot;Members List Interface&quot;">​</a></h3><p>The interface provides a comprehensive view of group membership:</p><ol><li><p><strong>Search Box</strong>: Filter the member list by name, username, or description</p><ul><li>Dynamically updates results as you type</li><li>Searches across multiple user fields simultaneously</li></ul></li><li><p><strong>Member Count</strong>: Shows the total number of users in the group</p><ul><li>Updates automatically when refreshing or when membership changes</li><li>Useful for quickly assessing group size</li></ul></li><li><p><strong>Refresh Button</strong>: Updates the member list with the latest data</p><ul><li>Useful after making changes to group criteria</li><li>Ensures the display matches current system state</li></ul></li></ol><h3 id="filtering-and-searching" tabindex="-1">Filtering and Searching <a class="header-anchor" href="#filtering-and-searching" aria-label="Permalink to &quot;Filtering and Searching&quot;">​</a></h3><p>Multiple tools help you find specific users within a group:</p><ol><li><p><strong>Global Search</strong>: Searches across all visible user fields</p><ul><li>Particularly useful for large groups</li><li>Case-insensitive matching</li></ul></li><li><p><strong>Column Sorting</strong>: Click column headers to sort the list</p><ul><li>Ascending or descending order</li><li>Useful for alphabetical organization or finding specific values</li></ul></li><li><p><strong>State Persistence</strong>: User interface preferences are remembered</p><ul><li>Column order and visibility</li><li>Sort preferences</li><li>Scroll position</li></ul></li></ol><h3 id="user-information-display" tabindex="-1">User Information Display <a class="header-anchor" href="#user-information-display" aria-label="Permalink to &quot;User Information Display&quot;">​</a></h3><p>Each user in the member list shows comprehensive information:</p><ol><li><p><strong>User Avatar</strong>: Shows the user&#39;s initials in a circular badge</p><ul><li>Uses first and last name</li><li>Provides visual identification</li></ul></li><li><p><strong>Basic Information</strong>:</p><ul><li>First Name</li><li>Last Name</li><li>Username</li><li>Description (if available)</li></ul></li><li><p><strong>Access Level</strong>: Color-coded chip showing user permission level</p><ul><li>User: Gray</li><li>Manager: Purple</li><li>Content Creator/Content: Green</li><li>Admin: Blue</li><li>Includes both the initial and full access level name</li></ul></li></ol><h2 id="assigned-knowledge-bases-component" tabindex="-1">Assigned Knowledge Bases Component <a class="header-anchor" href="#assigned-knowledge-bases-component" aria-label="Permalink to &quot;Assigned Knowledge Bases Component&quot;">​</a></h2><p>The Assigned Knowledge Bases component displays knowledge bases that are linked to the current group.</p><h3 id="knowledge-base-list" tabindex="-1">Knowledge Base List <a class="header-anchor" href="#knowledge-base-list" aria-label="Permalink to &quot;Knowledge Base List&quot;">​</a></h3><p>The interface shows all knowledge bases assigned to the group:</p><ol><li><p><strong>Knowledge Base Cards</strong>: Each KB is displayed with:</p><ul><li>KB Initials: In a circular avatar badge</li><li>KB Name: Primary identifier</li><li>KB Description: Additional context about the knowledge base</li></ul></li><li><p><strong>Empty State</strong>: When no knowledge bases are assigned</p><ul><li>Shows explanatory message</li><li>Provides a button to navigate to the Knowledge Base Manager</li><li>Explains how to make KB assignments</li></ul></li></ol><h3 id="managing-knowledge-base-assignments" tabindex="-1">Managing Knowledge Base Assignments <a class="header-anchor" href="#managing-knowledge-base-assignments" aria-label="Permalink to &quot;Managing Knowledge Base Assignments&quot;">​</a></h3><p>Group-KB relationships are managed through the Knowledge Base Manager:</p><ol><li><p><strong>Navigation Link</strong>: Button to access the KB Manager (<code>/assistant/kb/KBListView</code>)</p><ul><li>Available when no KBs are assigned</li><li>Allows quick navigation to make assignments</li></ul></li><li><p><strong>Assignment Process Note</strong>: Explains that KB assignments are made from the KB Manager</p><ul><li>Creates awareness of the correct workflow</li><li>Prevents confusion about assignment capabilities</li></ul></li></ol><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="query-builder" tabindex="-1">Query Builder <a class="header-anchor" href="#query-builder" aria-label="Permalink to &quot;Query Builder&quot;">​</a></h3><p>The Smart Group Builder uses a powerful query builder with extensive capabilities:</p><ol><li><p><strong>Available Fields</strong>: Broad range of user attributes to query against</p><ul><li>Standard fields (name, username, email)</li><li>Job-related fields (title, department, reports to)</li><li>System fields (creation date, access level)</li><li>Custom fields (employee ID, language preference)</li></ul></li><li><p><strong>Operator Types</strong>:</p><ul><li><strong>Contains</strong>: Partial text matching (case-insensitive)</li><li><strong>Equal</strong>: Exact value matching</li><li><strong>Not Equal</strong>: Excludes exact value matches</li><li><strong>Exists</strong>: Field has any value (not empty)</li><li><strong>Not Exist</strong>: Field is empty or null</li><li><strong>Starts With</strong>: Text begins with specified value</li></ul></li><li><p><strong>Complex Logic</strong>:</p><ul><li>Clone individual conditions</li><li>Clone entire condition groups</li><li>Nest condition groups for complex logical expressions</li></ul></li></ol><h3 id="system-information" tabindex="-1">System Information <a class="header-anchor" href="#system-information" aria-label="Permalink to &quot;System Information&quot;">​</a></h3><p>Advanced system information is available through an expandable panel:</p><ol><li><strong>Group ID</strong>: System-generated unique identifier</li><li><strong>Fields</strong>: Technical field information</li><li><strong>Filters</strong>: Raw filter data</li><li><strong>Updated</strong>: Last modification timestamp</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><h3 id="creating-effective-smart-groups" tabindex="-1">Creating Effective Smart Groups <a class="header-anchor" href="#creating-effective-smart-groups" aria-label="Permalink to &quot;Creating Effective Smart Groups&quot;">​</a></h3><ol><li><p><strong>Clear Naming Convention</strong>:</p><ul><li>Use descriptive names that reflect the group&#39;s purpose</li><li>Include department or function in the name when applicable</li><li>Avoid vague or overly generic names</li></ul></li><li><p><strong>Descriptive Information</strong>:</p><ul><li>Add comprehensive descriptions explaining the group&#39;s purpose</li><li>Document why the group exists and how membership is determined</li><li>Note any special considerations for the group</li></ul></li><li><p><strong>Query Construction</strong>:</p><ul><li>Start with simple queries and test before adding complexity</li><li>Use the preview functionality to verify membership matches expectations</li><li>Consider performance implications for very complex queries</li></ul></li></ol><h3 id="managing-group-membership-1" tabindex="-1">Managing Group Membership <a class="header-anchor" href="#managing-group-membership-1" aria-label="Permalink to &quot;Managing Group Membership&quot;">​</a></h3><ol><li><p><strong>Regular Reviews</strong>:</p><ul><li>Periodically check that group membership is appropriate</li><li>Verify that query logic still matches intended membership</li><li>Update criteria as organizational structures change</li></ul></li><li><p><strong>Documentation</strong>:</p><ul><li>Document the logic behind complex query conditions</li><li>Note the purpose of each condition group</li><li>Document any manual inclusions or exclusions</li></ul></li><li><p><strong>Testing Changes</strong>:</p><ul><li>Before saving, review the predicted membership changes</li><li>Check both added and removed users</li><li>Consider the impact on KB access and other permissions</li></ul></li></ol><hr><p>For additional assistance with Smart Group configuration, please contact your system administrator or refer to the advanced administration documentation.</p>',57)]))}const w=a(u,[["render",p]]);export{y as __pageData,w as default};
